def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D'
    if n == 99:
        return 'D'

    my_actions = [h[0] for h in history]
    opp_actions = [h[1] for h in history]
    opp_c = opp_actions.count('C')
    opp_d = n - opp_c

    if n >= 3 and opp_actions[-1] == 'D' and opp_actions[-2] == 'D' and opp_actions[-3] == 'D':
        return 'D'

    if n >= 5 and opp_d >= n * 0.8:
        return 'D'

    my_def_with_response = 0
    retal = 0
    for i in range(n - 1):
        if my_actions[i] == 'D':
            my_def_with_response += 1
            if opp_actions[i + 1] == 'D':
                retal += 1

    if n == 98:
        if opp_c >= 90 and retal == 0:
            return 'D'
        return 'C'

    my_last, opp_last = history[-1]

    if opp_last == 'D':
        if my_last == 'D':
            return 'C'
        else:
            if n >= 2 and opp_actions[-2] == 'D':
                return 'D'
            recent_my_D = any(my_actions[i] == 'D' for i in range(max(0, n - 3), n))
            if recent_my_D:
                return 'C'
            return 'D'
    else:
        if my_last == 'D':
            if my_def_with_response > 0 and retal == 0:
                if rng.random() < 0.8:
                    return 'D'
            return 'C'
        else:
            if my_def_with_response > 0 and retal == 0:
                if rng.random() < 0.8:
                    return 'D'
            if opp_c >= n * 0.8 and retal <= my_def_with_response * 0.2:
                if rng.random() < 0.4:
                    return 'D'
            return 'C'
